#define I2C_ADDRESS_INDEX (0)

#define RAM_ADDRESS_LENGTH (1)
#define RAM_ADDRESS_INDEX (0)

#define WRITE_RAM_BANK_INDEX (1)
#define WRITE_RAM_DATA_INDEX (3)

#define FIRST_RAM_ADDRESS (0x000)
#define FIRST_RAM_WAVE_ADDRESS (FIRST_RAM_ADDRESS)
#define LAST_RAM_ADDRESS (0x3FF)
#define BOS1921_RAM_SIZE_BYTE ((LAST_RAM_ADDRESS + 1) * sizeof(uint16_t))

#define SLICE_BLOCK_SIZE (3)
#define WAVE_BLOCK_SIZE (3)
#define LAST_RAM_WAVE_ADDRESS (0x2C)
#define MAXIMUM_NUMBER_OF_WAVE ((LAST_RAM_WAVE_ADDRESS - FIRST_RAM_ADDRESS + 1) / WAVE_BLOCK_SIZE)

#define FIRST_RAM_SLICE_ADDRESS (FIRST_RAM_ADDRESS + (MAXIMUM_NUMBER_OF_WAVE * WAVE_BLOCK_SIZE))
#define LAST_RAM_SLICE_ADDRESS (LAST_RAM_ADDRESS)
#define MAXIMUM_NUMBER_OF_SLICE ((LAST_RAM_SLICE_ADDRESS - FIRST_RAM_SLICE_ADDRESS) / SLICE_BLOCK_SIZE)

#define BOS1921_NBR_INPUT   (1)
#define BOS1921_NBR_OUTPUT  (1)

#define ADC_DAC_V_REFERENCE_MILLI_VOLT  (3600)
#define ADC_DAC_FEEDBACK_RATIO          (31) //TODO: make feedback ration variable for new BOS1921 features
#define ADC_DAC_VOLTAGE_RANGE           (ADC_DAC_V_REFERENCE_MILLI_VOLT * ADC_DAC_FEEDBACK_RATIO)

#define DAC_NB_BIT_RESOLUTION           (11)
#define DAC_NUMBER_OF_STEP              ((1<<DAC_NB_BIT_RESOLUTION) - 1)
#define DAC_RESOLUTION_MICRO_VOLT       ((ADC_DAC_VOLTAGE_RANGE * 1000) /  DAC_NUMBER_OF_STEP)
#define DAC_MAX_STEP_SUPPORTED          (1743) // Datasheet p.56, max value in REFERENCE reg output

#define ADC_NB_BIT_RESOLUTION           (10)
#define ADC_NUMBER_OF_STEP              ((1<<ADC_NB_BIT_RESOLUTION) - 1)
#define ADC_RESOLUTION_MICRO_VOLT       ((ADC_DAC_VOLTAGE_RANGE * 1000) / ADC_NUMBER_OF_STEP)

#define ABS(__x) ((__x) < 0 ? -(__x) : (__x))
#define BOS1921_OUT_RESOLUTION_MICRO_VOLT             (DAC_RESOLUTION_MICRO_VOLT)
#define BOS1921_OUT_MAX_VOLTAGE_MILLI_VOLT            ((DAC_RESOLUTION_MICRO_VOLT * DAC_MAX_STEP_SUPPORTED) / 1000)
#define BOS1921_OUT_MIN_VOLTAGE_MILLI_VOLT            (BOS1921_OUT_MAX_VOLTAGE_MILLI_VOLT * -1)
#define BOS1921_OUT_PEAK_TO_PEAK_VOLTAGE_MILLI_VOLT   (BOS1921_OUT_MAX_VOLTAGE_MILLI_VOLT + ABS(BOS1921_OUT_MIN_VOLTAGE_MILLI_VOLT))

#define BOS1921_IN_RESOLUTION_MICRO_VOLT      (ADC_RESOLUTION_MICRO_VOLT)
#define BOS1921_IN_MAX_VOLTAGE_MILLI_VOLT     ((BOS1921_IN_RESOLUTION_MICRO_VOLT * ADC_NUMBER_OF_STEP) / 1000)
#define BOS1921_IN_MIN_VOLTAGE_MILLI_VOLT     (BOS1921_IN_MAX_VOLTAGE_MILLI_VOLT * -1)

#define BOS1921_RESET_SOFTWARE_DELAY_MS     (10)

