//***********************************************
//		REFERENCE register - address 0x00
//***********************************************
#define BOS1921_REFERENCE_REG_DATA_SYNTH_MASK       (0xFFFF)
#define BOS1921_REFERENCE_REG_DATA_FIFO_MASK        (0xFFF)

#define BOS1921_REFERENCE_REG_DATA_SHIFT (0)

#define BOS1921_REFERENCE_REG_CLEAR_DATA_FIFO(value)      (value & ~BOS1921_REFERENCE_REG_DATA_FIFO_MASK)
#define BOS1921_REFERENCE_REG_CLEAR_DATA_SYNTH(value)      (value & ~BOS1921_REFERENCE_REG_DATA_SYNTH_MASK)

#define BOS1921_REFERENCE_REG_WRITE_DATA_FIFO(value)      ((value << BOS1921_REFERENCE_REG_DATA_SHIFT) & BOS1921_REFERENCE_REG_DATA_FIFO_MASK)
#define BOS1921_REFERENCE_REG_WRITE_DATA_SYNTH(value)      ((value << BOS1921_REFERENCE_REG_DATA_SHIFT) & BOS1921_REFERENCE_REG_DATA_SYNTH_MASK)

#define BOS1921_REFERENCE_REG_READ_DATA_FIFO(reg)         ((reg & BOS1921_REFERENCE_REG_DATA_FIFO_MASK) >> BOS1921_REFERENCE_REG_DATA_SHIFT)
#define BOS1921_REFERENCE_REG_READ_DATA_SYNTH(reg)         ((reg & BOS1921_REFERENCE_REG_DATA_SYNTH_MASK) >> BOS1921_REFERENCE_REG_DATA_SHIFT)

//***********************************************
//		ION_BL register - address 0x01
//***********************************************
#define BOS1921_ION_BL_REG_ION_SCALE_MASK  (0xFF)
