#define BOS1921_ION_BL_REG_FSWMAX_MASK     (0xC00)

#define BOS1921_ION_BL_REG_ION_SCALE_SHIFT (0)
#define BOS1921_ION_BL_REG_SB_SHIFT        (8)
#define BOS1921_ION_BL_REG_FSWMAX_SHIFT    (10)

#define BOS1921_ION_BL_REG_CLEAR_ION_SCALE(value)      (value & ~BOS1921_ION_BL_REG_ION_SCALE_MASK)
#define BOS1921_ION_BL_REG_CLEAR_SB(value)             (value & ~BOS1921_ION_BL_REG_SB_MASK)
#define BOS1921_ION_BL_REG_CLEAR_FSWMAX(value)         (value & ~BOS1921_ION_BL_REG_FSWMAX_MASK)

#define BOS1921_ION_BL_REG_WRITE_ION_SCALE(value)      ((value << BOS1921_ION_BL_REG_ION_SCALE_SHIFT) & BOS1921_ION_BL_REG_ION_SCALE_MASK)
#define BOS1921_ION_BL_REG_WRITE_SB(value)             ((value << BOS1921_ION_BL_REG_SB_SHIFT) & BOS1921_ION_BL_REG_SB_MASK)
#define BOS1921_ION_BL_REG_WRITE_FSWMAX(value)         ((value << BOS1921_ION_BL_REG_FSWMAX_SHIFT) & BOS1921_ION_BL_REG_FSWMAX_MASK)

#define BOS1921_ION_BL_REG_READ_ION_SCALE(reg)         ((reg & BOS1921_ION_BL_REG_ION_SCALE_MASK) >> BOS1921_ION_BL_REG_ION_SCALE_SHIFT)
#define BOS1921_ION_BL_REG_READ_SB(reg)                ((reg & BOS1921_ION_BL_REG_SB_MASK) >> BOS1921_ION_BL_REG_SB_SHIFT)
#define BOS1921_ION_BL_REG_READ_FSWMAX(reg)            ((reg & BOS1921_ION_BL_REG_FSWMAX_MASK) >> BOS1921_ION_BL_REG_FSWMAX_SHIFT)

//***********************************************
