#define BOS1921_DEADTIME_REG_DLS_SHIFT  (0)
#define BOS1921_DEADTIME_REG_DHS_SHIFT  (5)

#define BOS1921_DEADTIME_REG_CLEAR_DLS(value)      (value & ~BOS1921_DEADTIME_REG_DLS_MASK)
