#define BOS1921_KP_REG_WRITE_KP(value)          ((value << BOS1921_KP_REG_KP_SHIFT) & BOS1921_KP_REG_KP_MASK)
#define BOS1921_KP_REG_WRITE_XTRIGR(value)      ((value << BOS1921_KP_REG_XTRIGR_SHIFT) & BOS1921_KP_REG_XTRIGR_MASK)
#define BOS1921_KP_REG_WRITE_XTRIGF(value)      ((value << BOS1921_KP_REG_XTRIGF_SHIFT) & BOS1921_KP_REG_XTRIGF_MASK)

#define BOS1921_KP_REG_READ_KP(reg)             ((reg & BOS1921_KP_REG_KP_MASK) >> BOS1921_KP_REG_KP_SHIFT)
#define BOS1921_KP_REG_READ_XTRIGR(reg)         ((reg & BOS1921_KP_REG_XTRIGR_MASK) >> BOS1921_KP_REG_XTRIGR_SHIFT)
#define BOS1921_KP_REG_READ_XTRIGF(reg)         ((reg & BOS1921_KP_REG_XTRIGF_MASK) >> BOS1921_KP_REG_XTRIGF_SHIFT)

//***********************************************
//		KPA_KI register - address 0x04
//***********************************************
#define BOS1921_KPA_KI_REG_KPA_MASK      (0xFF)
