#define BOS1921_KPA_KI_REG_WRITE_KPA(value)        ((value << BOS1921_KPA_KI_REG_KPA_SHIFT) & BOS1921_KPA_KI_REG_KPA_MASK)
#define BOS1921_KPA_KI_REG_WRITE_KIBASE(value)     ((value << BOS1921_KPA_KI_REG_KIBASE_SHIFT) & BOS1921_KPA_KI_KIBASE_MASK)

#define BOS1921_KPA_KI_REG_READ_KPA(reg)            ((reg & BOS1921_KPA_KI_REG_KPA_MASK) >> BOS1921_KPA_KI_REG_KPA_SHIFT)
#define BOS1921_KPA_KI_REG_READ_KIBASE(reg)        ((reg & BOS1921_KPA_KI_KIBASE_MASK) >> BOS1921_KPA_KI_REG_KIBASE_SHIFT)

